INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('free-city-company-captain-guard', 'free-city', 10, 'Company Captain''s Guard', '계약대장 호위조', 'commander', 'command', 3, 'Company Exchange', '계약대 거래소', 820, 234, NULL, NULL, 8, 85, 36, 34, 34, 55, NULL, NULL, NULL, 34, 72, '["hired-company","roll-call"]', '["free-city-tunnel-axe-crews","free-city-builders-net-crews"]', 'Batons and short boarding axes, with a plate panel strapped over the chest. The guard carries the company''s contract tally in a sealed tin and keeps it within reach of the captain.', '경봉과 짧은 승선 도끼를 들고 가슴에 판 한 장을 동여맨다. 호위조는 계약 기록을 봉한 양철통에 넣어 다니며 그 통을 대장 손이 닿는 곳에 둔다.', 'Three layers: a fitted quilted coat under the chest plate, a work helmet painted with the company mark, and a strip of the hiring city''s colour tied on the left arm.', '세 겹이다. 몸에 맞춘 누빔 외투 위에 가슴판을 대고, 계약대 표지를 칠한 작업 철모를 쓰며, 왼팔에 고용한 도시의 색 띠를 묶는다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('free-city-city-charter-escort', 'free-city', 11, 'City Charter Escort', '도시 계약청 호위대', 'commander', 'command', 4, 'City Charter House', '도시 계약청', 1550, 372, 3, NULL, 10, 95, 44, 42, 40, 70, NULL, NULL, NULL, 34, 82, '["roll-call","shield-line","thin-clad"]', '["free-city-hired-hand-pole-crews","free-city-builders-breach-crews"]', 'Patrol shields and long batons, with plate cut from old riot gear over the chest and thighs. The Charter House picks its escort from the best-kept contract companies and pays for repairs to their plate itself.', '순찰 방패와 긴 경봉을 들고, 옛 진압 장구에서 오려 낸 판을 가슴과 허벅지에 댄다. 계약청은 가장 손질이 잘된 계약대에서 호위를 골라 뽑고, 판의 수리비도 직접 낸다.', 'Two layers: a thin fitted coat under the plate, a sash in the city colour across the chest, and the Charter House seal on a cord at the neck.', '두 겹이다. 판 아래에 얇게 맞춘 외투를 입고, 가슴에는 도시 색 띠를 비껴 두르며, 목에는 계약청 인장을 끈에 걸어 단다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('free-city-hired-hand-pole-crews', 'free-city', 20, 'Hired Hand Pole Crews', '일손 장대조', 'infantry', 'line', 1, 'Contract Hall', '계약 회관', 180, 52, NULL, NULL, 40, 66, 18, 24, 22, 10, NULL, NULL, NULL, 32, 42, '["hired-company","charge-breaker"]', '["free-city-rail-trolley-raiders","free-city-workshop-crossbow-crews"]', 'Long hauling poles tipped with hooks cut from pump pipe, held in leather porter harnesses that double as padding. Hands are hired by the shift and bring their own gloves.', '펌프 관을 잘라 만든 갈고리를 끝에 단 긴 짐 나르기 장대를 든다. 가죽 멜빵은 몸을 받치는 덧대 구실도 한다. 일손은 교대 단위로 고용되며 장갑은 제가 가져온다.', 'Five cheap layers: stacked quilted vests, rag-wrapped boots and the heavy hauling harness over everything, with no sleeve band and a strip of the hiring city''s colour tied on for the contract.', '값싼 다섯 겹이다. 겹쳐 입은 누빔 조끼, 헝겊으로 감은 장화, 그 위에 걸친 무거운 멜빵이며 소매 띠는 없고 계약 기간 동안만 고용한 도시의 색 띠를 묶는다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('free-city-contract-shield-company', 'free-city', 21, 'Contract Shield Company', '계약 방패대', 'infantry', 'line', 2, 'Contract Hall', '계약 회관', 440, 128, NULL, NULL, 36, 72, 24, 40, 26, 45, NULL, NULL, NULL, 30, 56, '["hired-company","shield-line"]', '["free-city-workshop-crossbow-crews","free-city-brass-count-riflemen"]', 'Patrol shields mended with rail clips and short truncheons, with padded vests and plate panels at the chest. Nobody pretends the shields stop a rifle round; they are for the crossbow bolt and the thrown spike.', '철로 죔쇠로 땜질한 순찰 방패와 짧은 경봉을 들고, 누빔 조끼 위 가슴에 판을 댄다. 방패가 소총탄을 막는다고 믿는 사람은 없다. 석궁 화살과 던진 철정을 막으려는 것이다.', 'Four layers: a quilted vest under the plate, felt boots with rubber soles and a converted work helmet, with the company mark on the helmet and the left shoulder.', '네 겹이다. 판 아래에 누빔 조끼를 입고, 고무창을 댄 펠트 장화를 신고, 고친 작업 철모를 쓰며, 철모와 왼쪽 어깨에 계약대 표지를 칠한다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('free-city-tunnel-axe-crews', 'free-city', 22, 'Tunnel Axe Crews', '갱도 도끼조', 'infantry', 'shock', 2, 'Contract Hall', '계약 회관', 480, 140, NULL, NULL, 28, 70, 36, 28, 38, 30, NULL, NULL, NULL, 36, 54, '["hired-company","tunnel-fighter"]', '["free-city-workshop-crossbow-crews","free-city-sled-scouts","free-city-rail-trolley-raiders"]', 'Short axes and pry bars for fighting between pillars and in stairwells, with knee pads cut from tyre rubber. The crews are hired for stations where a rifle line has no room to form.', '기둥 사이와 계단통에서 싸우는 짧은 도끼와 쇠지레를 들고, 타이어 고무를 오려 만든 무릎 보호대를 찬다. 소총 대열이 설 자리가 없는 역을 지키려고 고용된다.', 'Four layers for the tunnels: a short quilted jacket, padded trousers, felt boots with rubber overshoes and a knitted cap under the helmet, with the company mark at the shoulder.', '터널용 네 겹이다. 짧은 누빔 웃옷, 솜바지, 고무 덧신을 신은 펠트 장화, 철모 속 뜨개 모자를 쓰고 어깨에 계약대 표지를 단다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('free-city-contract-storm-company', 'free-city', 23, 'Contract Storm Company', '계약 돌격대', 'infantry', 'shock', 3, 'Company Exchange', '계약대 거래소', 950, 271, 6, 'implants', 24, 88, 42, 34, 52, 62, NULL, NULL, NULL, 32, 66, '["hired-company","wired-body","plate-biter","iron-dread"]', '["free-city-brass-count-riflemen","free-city-workshop-mortar-crews","free-city-flywheel-cart-shock-crews"]', 'Long-hafted axes with hooked backs for peeling plate, and plate panels bolted over padded vests. Many in the company carry reinforced legs or plated ribs fitted by guild surgeons on advance against the season''s pay. The contract says what happens to the ones who do not come out.', '철판을 뜯어내는 갈고리 등이 달린 긴 자루 도끼를 들고, 누빔 조끼 위에 판을 볼트로 죈다. 대원 다수가 철 삯에서 빼기로 하고 집도 조합에게 선불로 받은 보강 다리나 판 늑골을 달고 있다. 못 나온 사람을 어떻게 하는지는 계약서에 적혀 있다.', 'Three layers: a fitted coat under bolted plate, a dented work helmet with the company mark, and the hiring city''s colour on a strip that comes off when the contract ends.', '세 겹이다. 볼트로 죈 판 아래에 몸에 맞춘 외투를 입고, 계약대 표지를 칠한 찌그러진 작업 철모를 쓰며, 계약이 끝나면 푸는 고용 도시 색 띠를 두른다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('free-city-charter-heavy-company', 'free-city', 24, 'Charter Heavy Company', '계약청 중장대', 'infantry', 'line', 4, 'City Charter House', '도시 계약청', 1500, 428, 3, NULL, 24, 105, 46, 52, 46, 85, NULL, NULL, NULL, 28, 80, '["hired-company","shield-line","last-to-leave","thin-clad"]', '["free-city-passage-marksmen","free-city-brass-count-riflemen","free-city-rail-trolley-raiders"]', 'Riot shields faced with plate and long cutting axes, with plate panels bolted over padded vests. The company holds the line the city names and does not leave it before the contract does.', '판을 덧댄 진압 방패와 긴 절단 도끼를 들고, 누빔 조끼 위에 판을 볼트로 죈다. 이 계약대는 도시가 정한 선을 지키고, 계약이 끝나기 전에는 그 선을 떠나지 않는다.', 'Two layers under the plate: a knitted undershirt and a fitted coat, with the company mark on the helmet and the left shoulder and a strip of the hiring city colour.', '판 아래는 두 겹이다. 뜨개 속옷과 맞춤 외투를 입고, 철모와 왼쪽 어깨에 계약대 표지를 칠하며 고용 도시 색 띠를 묶는다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('free-city-brass-count-riflemen', 'free-city', 30, 'Brass-Count Riflemen', '탄피 세는 소총반', 'missile', 'rifle', 2, 'Contract Hall', '계약 회관', 525, 147, NULL, 'ammo', 28, 68, 16, 17, 24, 22, 20, 150, 14, 33, 56, '["hired-company","hand-loaded"]', '["free-city-hired-hand-pole-crews","free-city-tunnel-axe-crews"]', 'Bolt-action rifles of mixed origin loaded with hand-refilled rounds, and a brass sack on every belt. Magazines are counted at dawn, and a rifleman who leaves brass on the floor is fined.', '출처가 제각각인 볼트식 소총에 손으로 다시 채운 탄을 먹이고, 허리마다 탄피 자루를 찬다. 탄창은 새벽마다 세며, 탄피를 바닥에 두고 온 사수는 벌금을 문다.', 'Four layers: a long greatcoat over a quilted jacket, puttees over felt boots, and a helmet marked with the company sign, with a strip of the hiring city colour at the arm.', '네 겹이다. 누빔 웃옷 위에 긴 외투를 입고, 펠트 장화에 각반을 감고, 표지를 칠한 철모를 쓰며 팔에 고용 도시 색 띠를 묶는다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('free-city-workshop-crossbow-crews', 'free-city', 31, 'Workshop Crossbow Crews', '공방 석궁조', 'missile', 'skirmish', 2, 'Workshop Floor', '공방 조립장', 400, 90, NULL, NULL, 24, 66, 14, 14, 22, 12, 26, 130, 16, 36, 52, '["muscle-powered","quiet-step"]', '["free-city-hired-hand-pole-crews","free-city-contract-shield-company"]', 'Spring-steel crossbows built on workshop benches from rail clips, with short bolts cut from rebar. The strings are waxed and kept inside the coat against the cold.', '공방 작업대에서 철로 죔쇠로 만든 판스프링 석궁을 들고, 철근을 잘라 만든 짧은 화살을 쏜다. 시위는 밀랍을 먹여 추위를 피하도록 외투 안에 넣어 둔다.', 'Four layers: a quilted vest, a knitted hood and fingerless gloves with mitts over them, and a green band at the right sleeve for the workshop that built the bows.', '네 겹이다. 누빔 조끼, 뜨개 두건, 벙어리장갑을 덧낀 손가락 없는 장갑을 쓰고, 활을 만든 공방을 알리는 녹색 띠를 오른쪽 소매에 두른다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('free-city-rail-spike-throwers', 'free-city', 32, 'Rail Spike Throwers', '철정 투척조', 'missile', 'anti-armour', 2, 'Contract Hall', '계약 회관', 480, 120, NULL, NULL, 16, 72, 20, 20, 24, 25, 120, 70, 5, 34, 60, '["muscle-powered","machine-hunter","tunnel-fighter"]', '["free-city-tunnel-axe-crews","free-city-contract-shield-company","free-city-workshop-drop-drones"]', 'Finned rail spikes thrown from short spear-throwers at plate and engine housings. The crew collects every spike after the fight and straightens the bent ones on a bench.', '꼬리날개를 단 철로 못을 짧은 투창기로 던져 장갑판과 엔진 덮개를 노린다. 조원은 싸움이 끝나면 못을 모두 줍고 휜 것은 작업대에서 편다.', 'Three layers: a fitted coat, a leather apron over the chest and thick gloves, with a tool roll at the hip and a green band at the sleeve.', '세 겹이다. 몸에 맞춘 외투 위로 가슴을 덮는 가죽 앞치마를 두르고 두꺼운 장갑을 끼며, 허리에 공구 말이를 차고 소매에 녹색 띠를 두른다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('free-city-passage-marksmen', 'free-city', 33, 'Passage Marksmen', '통로 저격조', 'missile', 'marksman', 3, 'Company Exchange', '계약대 거래소', 1000, 250, 5, 'ammo', 12, 66, 18, 20, 22, 20, 85, 200, 10, 33, 64, '["skilled-crew","quiet-step"]', '["free-city-company-captain-guard","free-city-city-charter-escort","free-city-contract-storm-company"]', 'Long-barrelled bolt-action rifles with salvaged scopes, fired in pairs with a spotter. Each shooter draws ten rounds and signs for every one.', '떼어 온 조준경을 단 긴 총열의 볼트식 소총을 관측수와 짝지어 쏜다. 사수마다 열 발을 받으며 한 발씩 서명한다.', 'Three layers: a fitted quilted coat, a knitted hood with goggles and a grey scarf, and a small company mark stitched at the left shoulder.', '세 겹이다. 몸에 맞춘 누빔 외투, 보안경을 쓴 뜨개 두건, 회색 목도리를 두르고 왼쪽 어깨에 작은 계약대 표지를 꿰맨다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('free-city-workshop-mortar-crews', 'free-city', 34, 'Workshop Mortar Crews', '공방 박격포조', 'missile', 'artillery', 3, 'Company Exchange', '계약대 거래소', 1100, 275, 4, 'ammo', 12, 68, 14, 14, 20, 15, 140, 400, 9, 28, 62, '["skilled-crew"]', '["free-city-charter-heavy-company","free-city-hired-hand-pole-crews","free-city-company-captain-guard"]', 'Light mortars cast from salvaged pipe on a base plate of rail steel, carried in three parts. The crew counts every bomb and keeps the sight in an inner pocket so it does not freeze.', '떼어 온 관으로 만든 가벼운 박격포를 철로 강철 받침판에 올려 세 부분으로 나눠 멘다. 조원은 포탄을 한 발씩 세고, 조준기는 얼지 않도록 속주머니에 넣는다.', 'Three layers: a fitted quilted coat, a tool roll on the hip and padded gloves, with a green workshop tab at the shoulder.', '세 겹이다. 몸에 맞춘 누빔 외투를 입고, 허리에 공구 말이를 차고 솜장갑을 끼며, 어깨에 공방을 알리는 녹색 표를 단다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('free-city-rail-trolley-raiders', 'free-city', 40, 'Rail Trolley Raiders', '궤도 수레 습격대', 'fast', 'raider', 2, 'Track Shed', '궤도 정비고', 520, 130, NULL, NULL, 16, 105, 30, 20, 28, 22, NULL, NULL, NULL, 72, 56, '["rail-borne","quiet-step"]', '["free-city-workshop-crossbow-crews","free-city-passage-marksmen","free-city-fibre-scout-drones"]', 'Pump-driven rail trolleys fitted with boarding hooks and short cutting axes. The pumps run on arms, not fuel, and the crew carries oil only for the bearings.', '승선 갈고리와 짧은 절단 도끼를 단 펌프식 궤도 수레를 몬다. 펌프는 팔 힘으로 돌아가 연료가 들지 않고, 조원은 베어링용 기름만 지닌다.', 'Five layers for the tunnels and the open track: a short quilted jacket, padded trousers, felt boots with rubber overshoes and a knitted cap with a green band.', '터널과 노출 선로를 오가는 다섯 겹이다. 짧은 누빔 웃옷, 솜바지, 고무 덧신을 신은 펠트 장화, 녹색 띠를 두른 뜨개 모자를 쓴다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('free-city-sled-scouts', 'free-city', 41, 'Sled Scouts', '썰매 정찰조', 'fast', 'recon', 2, 'Track Shed', '궤도 정비고', 450, 100, NULL, NULL, 10, 92, 22, 18, 22, 15, NULL, NULL, NULL, 80, 52, '["frost-hardened","scout-deploy"]', '["free-city-brass-count-riflemen","free-city-workshop-mortar-crews","free-city-fibre-scout-drones"]', 'Plank sleds towed by rope across surface ice, with signal lamps, field glasses and hand flares. The scouts carry knives, not rifles; they run ahead, look and report.', '지상 얼음 위로 줄을 끌어 움직이는 널빤지 썰매에 신호등, 망원경, 손 조명탄을 싣는다. 정찰조는 소총 없이 칼만 차고 앞서 달려 보고 알린다.', 'Six layers for the surface: quilted jacket under a coarse greatcoat, padded trousers, felt boots and a hooded cap with goggles, with white cloth over the outer layer.', '지상용 여섯 겹이다. 거친 외투 아래에 누빔 웃옷, 솜바지, 펠트 장화, 보안경을 쓴 두건 모자를 쓰고 가장 바깥 겹에 흰 천을 덧씌운다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('free-city-flywheel-cart-shock-crews', 'free-city', 42, 'Flywheel Cart Shock Crews', '관성 수레 돌격조', 'fast', 'shock', 3, 'Track Shed', '궤도 정비고', 900, 225, NULL, NULL, 14, 150, 38, 26, 42, 42, NULL, NULL, NULL, 66, 64, '["rail-borne","tunnel-fighter"]', '["free-city-passage-marksmen","free-city-workshop-mortar-crews","free-city-builders-net-crews"]', 'Rail carts driven by flywheels that the crew spins up with hand cranks before the run, with ram bars and boarding hooks. The charge is short and loud, and the carts are cranked again before the next one.', '출발 전에 조원이 손 크랭크로 돌려 놓는 관성바퀴로 달리는 궤도 수레이며, 충각 막대와 승선 갈고리를 단다. 돌격은 짧고 시끄럽고, 다음 돌격 전에 수레를 다시 돌린다.', 'Three layers: a fitted quilted coat, a work helmet with a chin strap and thick gloves, with the company mark painted on the cart and a green band at the arm.', '세 겹이다. 몸에 맞춘 누빔 외투, 턱끈을 맨 작업 철모, 두꺼운 장갑을 착용하며 수레에 표지를 칠하고 팔에 녹색 띠를 두른다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('free-city-fibre-scout-drones', 'free-city', 50, 'Fibre Scout Drones', '줄조종 정찰 기체조', 'drone', 'recon', 2, 'Workshop Floor', '공방 조립장', 560, 140, 4, 'cells,parts', 6, 54, 10, 6, 18, 0, NULL, NULL, NULL, 78, 54, '["fibre-guided","scout-deploy"]', '["free-city-brass-count-riflemen","free-city-workshop-mortar-crews"]', 'Small rotor airframes steered through a thin cable on a hand reel, so jamming cannot reach them. The pilots keep the cell box inside the coat against the cold.', '손 릴에 감은 가는 줄로 조종하는 소형 회전익 기체로, 방해 전파가 닿지 않는다. 조종조는 전지 상자를 추위를 피해 외투 안에 품는다.', 'Four layers indoors: a quilted coat, a knitted hood and goggles, fingerless gloves and a cable reel on the hip, with a green piping on the collar.', '실내용 네 겹이다. 누빔 외투, 뜨개 두건과 보안경, 손가락 없는 장갑을 쓰고 허리에 줄 릴을 차며 깃에 녹색 선두름을 단다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('free-city-workshop-drop-drones', 'free-city', 51, 'Workshop Drop Drones', '공방 투하 비행조', 'drone', 'strike', 3, 'Assembly Works', '조립 공장', 1000, 250, 4, 'cells,parts', 6, 60, 10, 6, 18, 0, 120, 400, 2, 85, 60, '["radio-linked","skilled-crew"]', '["free-city-passage-marksmen","free-city-rail-spike-throwers","free-city-plated-ore-cart-rams"]', 'Six rotor airframes rebuilt from salvaged motors, each carrying a single drop charge. They are flown briefly and brought down fast, and the cells ride in padded pouches against the crew.', '떼어 온 모터로 다시 짠 회전익 기체 여섯 대가 각각 투하 폭약 하나를 단다. 잠깐 띄우고 빨리 내리며, 전지는 조원의 몸에 붙인 솜 주머니에 넣어 둔다.', 'Three layers: a heavy padded coat with inside pockets for the cells, a knitted hood and goggles, and a tool roll at the hip.', '세 겹이다. 전지를 넣을 안주머니가 달린 두꺼운 누빔 외투를 입고, 뜨개 두건과 보안경을 쓰며, 허리에 공구 말이를 찬다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('free-city-relay-strike-flight', 'free-city', 52, 'Relay Strike Flight', '중계 타격 편대', 'drone', 'strike', 4, 'Signal Works', '신호 공방', 1750, 420, 2, 'cells,parts', 8, 70, 12, 8, 20, 5, 190, 450, 3, 82, 78, '["radio-linked","skilled-crew","thin-clad"]', '["free-city-plated-gun-cars","free-city-company-captain-guard","free-city-workshop-mortar-crews"]', 'Eight larger rotor airframes with a relay mast flown ahead, so the flight can strike from farther than one pilot could steer alone. Each airframe carries a shaped charge and a heated cell.', '중계 안테나를 단 기체를 앞세워 날리면 조종사 혼자 닿는 거리보다 먼 곳을 칠 수 있다. 큰 회전익 기체 여덟 대가 각각 성형 폭약 하나와 데운 전지 하나를 싣는다.', 'Two layers: a thin fitted coat with inside pockets for the cells, a knitted hood with goggles, and a green piping at the cuffs.', '두 겹이다. 전지를 넣는 안주머니가 달린 얇은 맞춤 외투를 입고, 보안경을 쓴 뜨개 두건을 쓰며, 소맷부리에 녹색 선두름을 단다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('free-city-plated-ore-cart-rams', 'free-city', 60, 'Plated Ore Cart Rams', '장갑 광차 충차', 'war-machine', 'armour', 3, 'Armoured Trolley Yard', '장갑 수레 차고', 1000, 250, 4, 'cells,parts', 3, 4200, 26, 14, 260, 70, NULL, NULL, NULL, 36, 62, '["rail-borne","iron-dread"]', '["free-city-contract-shield-company","free-city-brass-count-riflemen","free-city-company-captain-guard"]', 'Ore carts plated with rail steel and pushed by cell-driven motors, with a ram beam on the front that breaks barricades. Each cart is rebuilt from scrap, so no two are alike.', '철로 강철을 덧댄 광차를 전지 모터로 밀며, 앞에는 방벽을 부수는 충각 들보가 달려 있다. 수레마다 고철로 다시 짜서 똑같은 것이 없다.', 'Each cart''s crew of three wears three layers in the cramped cab: a quilted coat, a leather cap and thick gloves, with a green band painted on the cart side.', '수레마다 조원 셋이 좁은 운전칸에서 세 겹을 입는다. 누빔 외투, 가죽 모자, 두꺼운 장갑을 착용하며 수레 옆면에 녹색 띠를 칠한다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('free-city-plated-gun-cars', 'free-city', 61, 'Plated Gun Cars', '장갑 포차', 'war-machine', 'armour', 4, 'Armoured Trolley Yard', '장갑 수레 차고', 1900, 475, 2, 'ammo,cells', 2, 5600, 18, 10, 250, 95, 220, 300, 14, 30, 78, '["rail-borne","thin-clad"]', '["free-city-charter-heavy-company","free-city-company-captain-guard","free-city-passage-marksmen"]', 'Rail cars plated with welded track steel, each with a short-barrelled gun that fires salvaged shells, driven by cell motors and held by a hand brake. Every shell is counted out of a locked box.', '용접한 궤도 강재를 두른 궤도 차량에 떼어 온 포탄을 쏘는 짧은 포신을 얹고, 전지 모터로 움직이며 손 제동기로 세운다. 포탄은 잠금 상자에서 한 발씩 세어 꺼낸다.', 'Each car''s crew wears two layers in the closed car: a thin fitted coat and a leather cap, with the city colour on a strip tied to the gun mantlet.', '차마다 조원은 닫힌 차 안에서 두 겹을 입는다. 얇은 맞춤 외투와 가죽 모자를 착용하며, 포 방패에 도시 색 띠를 묶는다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('free-city-builders-net-crews', 'free-city', 70, 'Builders'' Net Crews', '건축 조합 그물조', 'support', 'countermeasure', 1, 'Guild Hall', '기술 조합 회관', 260, 70, NULL, NULL, 12, 62, 12, 14, 18, 18, NULL, NULL, NULL, 33, 48, '["net-casting","quiet-step"]', '["free-city-workshop-drop-drones","free-city-relay-strike-flight"]', 'Weighted nets thrown from stair heads and ceiling hooks, with wire, poles and hand clamps for pulling a downed airframe in. The nets are the same ones the builders hang across exits.', '계단 머리와 천장 고리에서 던지는 추 달린 그물과, 떨어진 기체를 끌어당기는 철사, 장대, 손 집게를 쓴다. 그물은 건축 조합이 출구에 치는 것과 같은 그물이다.', 'Four layers: a fitted quilted coat, a hood and goggles against falling parts, and a builders'' mark stitched at the shoulder.', '네 겹이다. 몸에 맞춘 누빔 외투를 입고, 떨어지는 부품을 막는 두건과 보안경을 쓰며, 어깨에 건축 조합 표를 꿰맨다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('free-city-builders-breach-crews', 'free-city', 71, 'Builders'' Breach Crews', '건축 조합 돌파조', 'support', 'breacher', 3, 'Master Guild Hall', '장인 조합 회관', 800, 200, NULL, NULL, 12, 76, 24, 22, 34, 40, NULL, NULL, NULL, 32, 62, '["breach-charge","machine-hunter","tunnel-fighter"]', '["free-city-plated-ore-cart-rams","free-city-plated-gun-cars"]', 'Wall saws, wedge bars and shaped charges packed in tin, with shoring props carried on the back. The crews open sealed doors and barricades and also know where a cart body is weakest.', '벽 톱, 쐐기 막대, 양철통에 담은 성형 폭약을 쓰고 버팀목을 등에 진다. 닫힌 문과 방벽을 열고, 수레 차체가 어디서 약한지도 안다.', 'Three layers: a fitted quilted coat, a work helmet with a lamp and thick gloves, with a builders'' mark stitched at the left shoulder.', '세 겹이다. 몸에 맞춘 누빔 외투, 등을 단 작업 철모, 두꺼운 장갑을 착용하며 왼쪽 어깨에 건축 조합 표를 꿰맨다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('free-city-machinists-field-repair-crews', 'free-city', 72, 'Machinists'' Field Repair Crews', '기계 조합 현장 수리조', 'support', 'engineer', 3, 'Master Guild Hall', '장인 조합 회관', 740, 185, NULL, NULL, 12, 68, 14, 18, 20, 25, NULL, NULL, NULL, 34, 60, '["field-repair","tunnel-fighter"]', '["free-city-fibre-scout-drones","free-city-workshop-drop-drones"]', 'Wire coils, rail fasteners, a hand jack and hydraulic cutters, with spare belts for the carts. Many of the crew work with cable hands that need no charge and can be mended with a file and a spring.', '철사 뭉치, 궤도 죔쇠, 손 잭, 유압 절단기를 지니고 수레용 여벌 벨트를 챙긴다. 조원 가운데는 충전이 필요 없고 줄칼과 용수철로 고칠 수 있는 줄 손을 쓰는 사람이 많다.', 'Three layers: a fitted quilted coat with resewn seams, an apron full of pockets and a tool roll, with a machinists'' tab at the left shoulder.', '세 겹이다. 이음매를 거듭 기운 맞춤 누빔 외투 위에 주머니가 가득한 앞치마를 두르고 공구 말이를 차며, 왼쪽 어깨에 기계 조합 표를 단다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('free-city-linesmen-static-veil-teams', 'free-city', 73, 'Linesmen Static Veil Teams', '전선 조합 잡음 장막반', 'support', 'countermeasure', 4, 'Signal Works', '신호 공방', 1400, 330, 2, NULL, 10, 64, 12, 14, 18, 20, NULL, NULL, NULL, 32, 76, '["static-veil","quiet-step","thin-clad"]', '["free-city-workshop-drop-drones","free-city-relay-strike-flight"]', 'Cell-powered jammers on carrying frames and coils of copper wire, with the cells kept warm in padded boxes. The teams switch the jammers on only when an enemy airframe is in the air.', '들것 틀에 얹은 전지식 방해기와 구리선 뭉치를 지니며, 전지는 솜 상자에 넣어 따뜻하게 둔다. 적 기체가 떠 있을 때만 방해기를 켠다.', 'Two layers: a thin fitted coat and a hood, with a twist of copper wire at the left shoulder and a green piping at the collar.', '두 겹이다. 얇은 맞춤 외투와 두건을 쓰고, 왼쪽 어깨에 구리선 꼬임을 달며 깃에 녹색 선두름을 단다.', NULL);
